const fs = require('fs');
const body = $('Webhook Start (Test)').first().json.body || {};
const execId = $execution.id;
const dealId = body.deal_id || String(execId);
const config = {
  mode: 'skip-gate',
  folder: body.deal_folder,
  deal_id: dealId,
  run_id: String(execId),
  tmp_dir: '/tmp',
  skip_gate: true
};
const path = '/tmp/om-screener-test-' + execId + '.json';
fs.writeFileSync(path, JSON.stringify(config));
return [{ json: { configPath: path } }];
